                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and g[x][y]==c and not seen[x][y]:
                            seen[x][y]=True; q.append((x,y))
                # pattern bbox from the seed comp (use this comp's bbox)
                R0=min(r for r,_ in cs); R1=max(r for r,_ in cs)
                C0=min(b for _,b in cs); C1=max(b for _,b in cs)
                hh,ww=R1-R0+1,C1-C0+1
                P=[[0]*ww for _ in range(hh)]
                for (a,b) in [(a,b) for a in range(R0,R1+1) for b in range(C0,C1+1) if g[a][b]==c]:
