                    for r1 in range(R0,H):
                        if r1-r0+1 < hh: continue
                        for c0 in range(0,C0+1):
                            for c1 in range(C0,W):
                                if (r1-r0+1)%hh==0 and (c1-c0+1)%ww==0 and ok(r0,r1,c0,c1):
                                    cands.append(((r1-r0+1)*(c1-c0+1),r0,r1,c0,c1))
